package games.enchanted.eg_particle_interactions.common.mixin.client.blocks;
import games.enchanted.eg_particle_interactions.common.config.ConfigOptions; import games.enchanted.eg_particle_interactions.common.particle.ParticleSpawner; import net.minecraft.block.AbstractFurnaceBlock; import net.minecraft.block.BlockState; import net.minecraft.block.SmokerBlock; import net.minecraft.util.math.BlockPos; import net.minecraft.world.World; import org.spongepowered.asm.mixin.Mixin; import org.spongepowered.asm.mixin.injection.At; import org.spongepowered.asm.mixin.injection.Inject; import org.spongepowered.asm.mixin.injection.callback.CallbackInfo; import java.util.Random;
@Mixin(SmokerBlock.class) public abstract class SmokerBlockMixin {
 @Inject(method="randomDisplayTick",at=@At("TAIL")) private void egpi$smoke(BlockState s,World w,BlockPos p,Random r,CallbackInfo ci){if(ConfigOptions.get().enabled&&ConfigOptions.get().fireAndFurnaces&&s.get(AbstractFurnaceBlock.LIT)&&r.nextInt(4)==0)ParticleSpawner.furnace(w,p);}
}
